export function makeProfile({holeScale=parameters.holeScale}={}){
 if(!Number.isFinite(holeScale)||holeScale<=0)throw Error('Hole scale must be positive');
 return {...frame,depth:parameters.depth,outline,cutouts:[
  ...holePatterns.flatMap(g=>g.centers.map(center=>[{kind:'circle',center,radius:g.diameter*holeScale/2}])),
  ...contourInstances.map(i=>placeContour(contours[i.template],i.center,i.matrix))
 ]};
}
export const profile=makeProfile();
export default function build({depth=parameters.depth,holeScale=parameters.holeScale}={}){
 return buildPrismaticPart(makeProfile({holeScale}),{depth,holeScale:1});
}
